{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Nomegestrol acetate, the closest structural analogue (19-nor, 17α-acetoxy progestin), has an absolute oral bioavailability of 63.4% in healthy women, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Chlormadinone acetate, another 17α-acetoxy progestin, shows approximately 100% oral bioavailability in humans, supporting high oral bioavailability for this steroid acetate class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Norethisterone acetate, a 19-nor progestin acetate, has absolute oral bioavailability between 47% and 73% in women, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Medroxyprogesterone acetate has low oral bioavailability (<10%) in humans, providing a contradictory anchor; however, its C19-methyl and 6-methyl features are less transferable to the 19-nor, 11-aryl query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue (nomegestrol acetate) and several 17α-acetoxy/19-nor progestins show absolute oral bioavailability ≥60%, while the main low-bioavailability analogue (medroxyprogesterone acetate) is less structurally transferable. Weighing direct human absolute-F data and structural similarity, the query is more likely to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for the query molecule (ulipristal acetate-like structure) are provided.",
    "No mifepristone or other 11β-aryl steroid analogue is included in the evidence set.",
    "The conflicting low-F result for medroxyprogesterone acetate leaves uncertainty about solubility-limited absorption in highly lipophilic steroid acetates."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

